"""Recursive-descent parser for the minisql grammar.

Grammar (exactly this, nothing more):

    query     := SELECT select_list FROM ident
                 [ WHERE ident op literal ]
                 [ ORDER BY ident [ ASC | DESC ] ] EOF
    select_list := '*' | ident ( ',' ident )*
    op        := '=' | '!=' | '<' | '<=' | '>' | '>='
    literal   := number | string
"""

from .tokenizer import tokenize, TokenizeError


class ParseError(Exception):
    """Parse error with a message and character position in the SQL string."""

    def __init__(self, message, pos):
        super().__init__(message)
        self.message = message
        self.pos = pos


class Select:
    __slots__ = ("columns", "table", "where_col", "where_op", "where_value",
                 "order_col", "order_desc")

    def __init__(self):
        self.columns = None       # None means '*'
        self.table = None
        self.where_col = None
        self.where_op = None
        self.where_value = None
        self.order_col = None
        self.order_desc = False

    def __repr__(self):  # pragma: no cover - debugging aid
        return (
            f"Select(columns={self.columns}, table={self.table!r}, "
            f"where=({self.where_col!r} {self.where_op} {self.where_value!r}), "
            f"order=({self.order_col!r}, desc={self.order_desc}))"
        )


class Parser:
    def __init__(self, sql):
        try:
            self.tokens = tokenize(sql)
        except TokenizeError as exc:
            raise ParseError(exc.message, exc.pos) from None
        self.i = 0

    # -- helpers -----------------------------------------------------------

    def peek(self):
        return self.tokens[self.i]

    def advance(self):
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def error(self, message, tok=None):
        pos = self.peek().pos if tok is None else tok.pos
        raise ParseError(message, pos)

    def expect_keyword(self, keyword):
        tok = self.peek()
        if tok.kind != "keyword" or tok.value != keyword:
            expected = f"'{keyword}'"
            found = self._describe(tok)
            self.error(f"expected {expected}, found {found}", tok)
        return self.advance()

    def expect_ident(self, what="column name"):
        tok = self.peek()
        if tok.kind != "ident":
            found = self._describe(tok)
            self.error(f"expected {what}, found {found}", tok)
        return self.advance().value

    @staticmethod
    def _describe(tok):
        if tok.kind == "eof":
            return "end of input"
        return repr(tok.value)

    # -- grammar -----------------------------------------------------------

    def parse(self):
        node = Select()

        self.expect_keyword("SELECT")
        node.columns = self._parse_select_list()

        self.expect_keyword("FROM")
        node.table = self.expect_ident("table name")

        if self.peek().kind == "keyword" and self.peek().value == "WHERE":
            self.advance()
            node.where_col = self.expect_ident("column name after WHERE")
            node.where_op = self._parse_operator()
            node.where_value = self._parse_literal()

        if self.peek().kind == "keyword" and self.peek().value == "ORDER":
            self.advance()
            self.expect_keyword("BY")
            node.order_col = self.expect_ident("column name after ORDER BY")
            if self.peek().kind == "keyword" and self.peek().value in ("ASC", "DESC"):
                node.order_desc = self.advance().value == "DESC"

        tok = self.peek()
        if tok.kind != "eof":
            self.error(f"unexpected trailing input {self._describe(tok)}", tok)

        return node

    def _parse_select_list(self):
        tok = self.peek()
        if tok.kind == "op" and tok.value == "*":
            self.advance()
            return None
        columns = [self.expect_ident("column name or '*'")]
        while self.peek().kind == "op" and self.peek().value == ",":
            self.advance()
            columns.append(self.expect_ident("column name after ','"))
        return columns

    def _parse_operator(self):
        tok = self.peek()
        if tok.kind != "op":
            self.error(
                f"expected comparison operator (=, !=, <, <=, >, >=), found {self._describe(tok)}",
                tok,
            )
        return self.advance().value

    def _parse_literal(self):
        tok = self.peek()
        if tok.kind in ("number", "string"):
            return self.advance().value
        self.error(f"expected literal (number or 'string'), found {self._describe(tok)}", tok)


def parse(sql):
    """Parse a minisql SELECT statement into a Select AST node."""
    return Parser(sql).parse()

