"""Executor for minisql: loads CSV tables and runs a parsed SELECT.

Value typing rule shared with the test suite (which loads the same CSVs
into sqlite3): a cell that looks like an integer becomes an ``int``,
one that looks like a decimal number becomes a ``float``, everything
else stays a ``str``.  This makes numeric-looking values compare
numerically, matching SQLite when the same typed values are inserted.
"""

import csv
import os
import re

from .parser import parse

_INT_RE = re.compile(r"^-?\d+$")
_FLOAT_RE = re.compile(r"^-?\d+\.\d+$")


def infer_value(text):
    """Convert a raw CSV cell to int/float/str using the shared typing rule."""
    s = text.strip()
    if _INT_RE.match(s):
        return int(s)
    if _FLOAT_RE.match(s):
        return float(s)
    return text


def load_table(name, cwd=None):
    """Load <name>.csv from cwd (default: current working directory).

    Returns (columns, rows) where rows are lists of typed Python values.
    """
    path = os.path.join(cwd or os.getcwd(), name + ".csv")
    if not os.path.exists(path):
        raise FileNotFoundError(f"no such table: {name!r} (looked for {path})")
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        try:
            columns = next(reader)
        except StopIteration:
            raise ValueError(f"table file {path} is empty") from None
        rows = [[infer_value(cell) for cell in row] for row in reader]
    return columns, rows


def _sort_key(value):
    """Total ordering across types: numbers before strings (like SQLite)."""
    if isinstance(value, bool):  # pragma: no cover - never produced here
        return (0, float(value))
    if isinstance(value, (int, float)):
        return (0, value)
    return (1, str(value))


def _compare(left, op, right):
    try:
        if op == "=":
            return left == right
        if op == "!=":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
    except TypeError:
        raise TypeError(
            f"cannot compare {left!r} with {right!r} using '{op}'"
        ) from None
    raise ValueError(f"unknown operator {op!r}")


def execute(sql, cwd=None):
    """Run one minisql SELECT statement.

    Returns (columns, rows): the output column names and result rows as
    lists of Python values.
    """
    node = parse(sql)
    table_columns, rows = load_table(node.table, cwd)
    index = {col.strip(): i for i, col in enumerate(table_columns)}

    def col_idx(name):
        if name not in index:
            raise KeyError(f"no such column: {name!r} in table {node.table!r}")
        return index[name]

    # WHERE
    if node.where_col is not None:
        wi = col_idx(node.where_col)
        rows = [r for r in rows if _compare(r[wi], node.where_op, node.where_value)]

    # ORDER BY (stable sort)
    if node.order_col is not None:
        oi = col_idx(node.order_col)
        rows = sorted(rows, key=lambda r: _sort_key(r[oi]), reverse=node.order_desc)

    # SELECT list
    if node.columns is None:
        return list(table_columns), [list(r) for r in rows]

    out_idx = [col_idx(c) for c in node.columns]
    return list(node.columns), [[r[i] for i in out_idx] for r in rows]

